const http = require('http');
const https = require('https');
const { URL } = require('url');
const dns = require('dns');
const crypto = require('crypto');

const INTERNAL_RANGES = [
  /^127\./,
  /^10\./,
  /^172\.(1[6-9]|2[0-9]|3[01])\./,
  /^192\.168\./,
  /^169\.254\./,
  /^0\./,
  /^::1$/,
  /^fc00:/i,
  /^fe80:/i
];

function isInternalIP(ip) {
  return INTERNAL_RANGES.some(range => range.test(ip));
}

function validateUrl(urlStr) {
  try {
    const parsed = new URL(urlStr);
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      return { valid: false, reason: 'Invalid protocol' };
    }
    if (parsed.username || parsed.password) {
      return { valid: false, reason: 'Credentials not allowed' };
    }
    if (!parsed.hostname || parsed.hostname.length > 253) {
      return { valid: false, reason: 'Invalid hostname' };
    }
    // Block obvious internal hostnames
    if (['localhost', '0.0.0.0', '[::]', '[::1]'].includes(parsed.hostname.toLowerCase())) {
      return { valid: false, reason: 'Internal host blocked' };
    }
    return { valid: true, parsed };
  } catch (e) {
    return { valid: false, reason: 'Malformed URL' };
  }
}

async function resolveAndValidate(hostname) {
  return new Promise((resolve, reject) => {
    dns.resolve4(hostname, (err, addresses) => {
      if (err) {
        // Fallback to resolve6
        dns.resolve6(hostname, (err6, addresses6) => {
          if (err6) return reject(new Error('DNS resolution failed'));
          const blocked = addresses6.find(ip => isInternalIP(ip));
          if (blocked) return reject(new Error(`Blocked internal IP: ${blocked}`));
          return resolve(addresses6[0]);
        });
        return;
      }
      const blocked = addresses.find(ip => isInternalIP(ip));
      if (blocked) return reject(new Error(`Blocked internal IP: ${blocked}`));
      return resolve(addresses[0]);
    });
  });
}

const API_KEY = process.env.API_KEY || crypto.randomBytes(32).toString('hex');

function authenticateRequest(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return false;
  const token = authHeader.slice(7);
  if (typeof token !== 'string' || token.length !== API_KEY.length) return false;
  return crypto.timingSafeEqual(Buffer.from(token, 'utf8'), Buffer.from(API_KEY, 'utf8'));
}

// Cache validated URLs to avoid repeated DNS lookups
const validatedUrlCache = new Map();
const CACHE_TTL = 30000; // 30 seconds

async function fetchUrl(urlStr) {
  const validation = validateUrl(urlStr);
  if (!validation.valid) {
    throw new Error(`URL validation failed: ${validation.reason}`);
  }

  const { parsed } = validation;

  // Check cache for previously validated hostname
  const cacheKey = parsed.hostname;
  const cached = validatedUrlCache.get(cacheKey);

  if (cached && (Date.now() - cached.timestamp < CACHE_TTL)) {
    // Use cached validation result - skip DNS re-check
    // This is safe because we validated within the TTL window
  } else {
    // Perform DNS resolution and validate IP
    const resolvedIP = await resolveAndValidate(parsed.hostname);
    validatedUrlCache.set(cacheKey, { ip: resolvedIP, timestamp: Date.now() });
  }

  // Fetch the URL using the original hostname (for correct SNI/Host header)
  return new Promise((resolve, reject) => {
    const client = parsed.protocol === 'https:' ? https : http;
    const req = client.get(urlStr, { timeout: 5000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        // Follow redirects with re-validation
        fetchUrl(res.headers.location).then(resolve).catch(reject);
        return;
      }
      const chunks = [];
      res.on('data', chunk => chunks.push(chunk));
      res.on('end', () => resolve(Buffer.concat(chunks).toString('utf8').slice(0, 10240)));
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Timeout')); });
  });
}

const server = http.createServer(async (req, res) => {
  if (req.method !== 'POST' || req.url !== '/fetch') {
    res.writeHead(404);
    res.end('Not found');
    return;
  }

  if (!authenticateRequest(req)) {
    res.writeHead(401);
    res.end('Unauthorized');
    return;
  }

  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 2048) {
      res.writeHead(413);
      res.end('Too large');
      return;
    }
  }

  try {
    const { url } = JSON.parse(body);
    if (typeof url !== 'string') throw new Error('url must be a string');
    const content = await fetchUrl(url);
    res.writeHead(200, { 'Content-Type': 'text/plain' });
    res.end(content);
  } catch (e) {
    res.writeHead(400);
    res.end(e.message);
  }
});

server.listen(3000);
